import { useEffect, useState } from 'react';
import { adminRequest } from '../api/admin.js';
import { adminContent } from '../data/adminContent.js';
import { Icon } from './ui.jsx';

const text = adminContent.admins;

/** Reads username/password inputs and checks the confirmation before sending anything. */
function readCredentials(form, requirePassword) {
  const input = new FormData(form);
  const password = input.get('password');
  if (password !== input.get('confirm')) return { mismatch: true };
  if (!password && requirePassword) return { mismatch: true };
  return { username: input.get('username').trim(), password };
}

/** Lists, creates, renames, re-passwords, and deletes administrator accounts. */
export function AdminUsers({ session, disabled, onSessionChange, onError }) {
  const [admins, setAdmins] = useState(null);
  const [editing, setEditing] = useState('');
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');

  useEffect(() => {
    const controller = new AbortController();
    adminRequest('/admins', { signal: controller.signal })
      .then(result => setAdmins(result.admins))
      .catch(failure => { if (controller.signal.aborted) return; if (failure.status === 401) onError(failure); else setError(failure.message); });
    return () => controller.abort();
  }, [onError]);

  /** Runs one account change, then refreshes the list and shows a confirmation. */
  async function run(action, success) {
    setBusy(true); setMessage(''); setError('');
    try {
      await action();
      const result = await adminRequest('/admins');
      setAdmins(result.admins);
      setMessage(success);
      return true;
    } catch (failure) {
      if (failure.status === 401) onError(failure); else setError(failure.message);
      return false;
    } finally { setBusy(false); }
  }

  /** Creates a new administrator from the add form. */
  async function create(event) {
    event.preventDefault();
    const form = event.currentTarget;
    const { username, password, mismatch } = readCredentials(form, true);
    if (mismatch) { setError(text.mismatch); return; }
    if (await run(() => adminRequest('/admins', { method: 'POST', csrfToken: session.csrfToken, body: { username, password } }), text.created(username))) form.reset();
  }

  /** Saves a rename and/or password change for one administrator. */
  async function update(event, current) {
    event.preventDefault();
    const { username, password, mismatch } = readCredentials(event.currentTarget, false);
    if (mismatch) { setError(text.mismatch); return; }
    const body = { ...(username !== current ? { username } : {}), ...(password ? { password } : {}) };
    if (!Object.keys(body).length) { setEditing(''); return; }
    let renamedSelf = '';
    const saved = await run(async () => {
      const result = await adminRequest(`/admins/${encodeURIComponent(current)}`, { method: 'PUT', csrfToken: session.csrfToken, body });
      if (result.current !== session.username) renamedSelf = result.current;
    }, text.updated(username));
    if (saved) { setEditing(''); if (renamedSelf) onSessionChange({ ...session, username: renamedSelf }); }
  }

  /** Deletes another administrator after confirmation. */
  async function remove(username) {
    if (!window.confirm(text.deleteQuestion(username))) return;
    await run(() => adminRequest(`/admins/${encodeURIComponent(username)}`, { method: 'DELETE', csrfToken: session.csrfToken }), text.deleted(username));
  }

  const locked = disabled || busy;
  return <div className="admin-users">
    <div className="admin-editor-toolbar"><div><h2>{text.title}</h2><p>{text.description}</p></div></div>
    <p className="admin-save-status" role="status">{admins ? message : text.loading}</p>
    {error && <div role="alert" className="admin-error"><p>{error}</p></div>}
    {admins && <ul className="admin-user-list">{admins.map(username => <li key={username} className="admin-record">
      {editing === username ? <form className="admin-user-form" onSubmit={event => update(event, username)}>
        <label htmlFor={`admin-name-${username}`}>{adminContent.username}</label><input id={`admin-name-${username}`} name="username" defaultValue={username} required minLength={3} maxLength={64} pattern="[a-zA-Z0-9._\-]+" autoComplete="off" disabled={locked} />
        <label htmlFor={`admin-password-${username}`}>{text.newPassword}</label><input id={`admin-password-${username}`} name="password" type="password" minLength={12} maxLength={256} autoComplete="new-password" disabled={locked} />
        <label htmlFor={`admin-confirm-${username}`}>{text.confirmPassword}</label><input id={`admin-confirm-${username}`} name="confirm" type="password" minLength={12} maxLength={256} autoComplete="new-password" disabled={locked} />
        <div className="admin-record-tools"><button type="submit" className="admin-primary" disabled={locked}><Icon name="fa-floppy-disk" />{text.save}</button><button type="button" disabled={locked} onClick={() => setEditing('')}>{text.cancel}</button></div>
      </form> : <div className="admin-record-heading"><h4>{username} {username === session.username && <span className="admin-user-you">{text.you}</span>}</h4><div className="admin-record-tools">
        <button type="button" title={text.edit} aria-label={`${text.edit}: ${username}`} disabled={locked} onClick={() => { setEditing(username); setMessage(''); setError(''); }}><Icon name="fa-pen" /></button>
        <button type="button" title={text.delete} aria-label={`${text.delete}: ${username}`} disabled={locked || username === session.username} onClick={() => remove(username)}><Icon name="fa-trash" /></button>
      </div></div>}
    </li>)}</ul>}
    <form className="admin-user-form admin-user-add" onSubmit={create}>
      <h3>{text.add}</h3>
      <label htmlFor="new-admin-username">{adminContent.username}</label><input id="new-admin-username" name="username" required minLength={3} maxLength={64} pattern="[a-zA-Z0-9._\-]+" autoComplete="off" disabled={locked} />
      <label htmlFor="new-admin-password">{adminContent.password}</label><input id="new-admin-password" name="password" type="password" required minLength={12} maxLength={256} autoComplete="new-password" aria-describedby="new-admin-password-hint" disabled={locked} />
      <p id="new-admin-password-hint">{text.passwordHint}</p>
      <label htmlFor="new-admin-confirm">{text.confirmPassword}</label><input id="new-admin-confirm" name="confirm" type="password" required minLength={12} maxLength={256} autoComplete="new-password" disabled={locked} />
      <button type="submit" className="admin-primary" disabled={locked}><Icon name="fa-user-plus" />{text.add}</button>
    </form>
  </div>;
}
